export const requestAdSuggestions = async (
  qt: string
): Promise<AdMarketplaceData> => {
  const adSuggestionsDefault = {
    original_qt: qt,
    paid_suggestions: [],
    organic_suggestions: [],
  };

  if (!qt) return adSuggestionsDefault;

  try {
    let ip = localStorage.getItem('ip');

    if (!ip) {
      const response = await fetch('https://api.ipify.org?format=json');
      const { ip: newIp } = await response.json();
      localStorage.setItem('ip', newIp);
      ip = newIp;
    }

    // '96.41.207.187'
    const qs = new URLSearchParams({
      qt,
      partner: 'oceanhero_extn_cps',
      sub1: 'oceanhero',
      v: '1.4',
      ...(ip && { ip }),
    });

    const url = `https://${qs.get(
      'partner'
    )}.cps.ampfeed.com/suggestions?${qs}`;
    if (!inMemory[url]) {
      const response = await fetch(url, { signal: timeoutSignal(1000) });
      inMemory[url] = response.status === 200 ? await response.json() : null;
    }

    return inMemory[url];
  } catch (err) {
    console.error('requestAdSuggestions', err);
    return adSuggestionsDefault;
  }
};

export const findTakeMerchants = async (q: string) => {
  const { countryCode = 'US' } = (await getStorageItems([
    'countryCode',
  ])) as any;

  const merchants = await fetch(
    process.env.APP_URL + '/api/suggest/take?country=' + countryCode + '&q=' + q
  ).then((res) => res.json());

  return merchants || [];
};

